-- Abracadabra / Assist: the 'Suggestion' chip and its target template (generated 2026-09-15 from the local seeds)
-- Idempotent: re-running changes nothing. Run in one transaction.
BEGIN;

-- 1. Rename the intent row in place (keeps its id and any admin keyword edits) and give it its target.
UPDATE "IntentKeywordMap" SET label = 'Suggestion', "targetTemplateName" = COALESCE("targetTemplateName", 'Send Notification'), "updatedAt" = now() WHERE label = 'Notification';

-- 2. The full Assist / NL Rules catalogue — inserted only where the label is missing (prod may never have been seeded).
INSERT INTO "IntentKeywordMap" (id, label, keywords, action, "diagramType", "defaultLabel", "targetCategory", "targetTemplateName", "sortOrder", "createdAt", "updatedAt")
  SELECT gen_random_uuid()::text, 'Approval', ARRAY['approve', 'approval', 'sign-off', 'sign off', 'authorise', 'authorize', 'review', 'endorse', 'ratify']::text[], 'suggest-template', 'all', NULL, 'Approvals', NULL, 10, now(), now()
